import Image from "next/image";
import { connectToDatabase } from "@/lib/mongodb";
import Business from "@/models/Business";

interface IBusinessData {
    _id: string;
    business: string;
    image: string;
    service: string;
    contact: string;
    email: string;
    createdAt?: string;
    updatedAt?: string;
}

async function getBusinesses(): Promise<IBusinessData[]> {
    try {
        await connectToDatabase();
        const businesses = await Business.find().sort({ createdAt: -1 }).lean();
        return businesses as unknown as IBusinessData[];
    } catch (error) {
        console.error("Failed to fetch businesses:", error);
        return [];
    }
}

export default async function BusinessesPage() {
    const businesses: IBusinessData[] = await getBusinesses();

    if (!businesses || businesses.length === 0) {
        return (
            <div className="max-w-6xl mx-auto p-6">
                <h1 className="text-3xl font-bold mb-6">Businesses</h1>
                <p className="text-gray-500">No businesses found.</p>
            </div>
        );
    }

    return (
        <div className="max-w-6xl mx-auto p-6">
            <h1 className="text-3xl font-bold mb-6">
                Businesses
            </h1>

            <div className="grid md:grid-cols-3 gap-6">
                {businesses.map((business: IBusinessData) => (
                    <div
                        key={business._id}
                        className="bg-white shadow rounded-lg overflow-hidden"
                    >
                        {business.image ? (
                            <Image
                                src={business.image}
                                alt={business.business}
                                width={400}
                                height={200}
                                className="w-full h-48 object-cover"
                                priority={false}
                                onError={(e) => {
                                    const img = e.currentTarget as HTMLImageElement;
                                    img.src = "https://via.placeholder.com/400x200?text=No+Image";
                                }}
                            />
                        ) : (
                            <div className="w-full h-48 bg-gray-200 flex items-center justify-center">
                                <span className="text-gray-400">No image available</span>
                            </div>
                        )}

                        <div className="p-4">
                            <h2 className="text-xl font-semibold">
                                {business.business}
                            </h2>

                            <p className="text-gray-600 mt-2">
                                {business.service}
                            </p>

                            <p className="mt-2">
                                 {business.contact}
                            </p>

                            <p>
                                ✉️ {business.email}
                            </p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

import Image from "next/image";
